import { FC, HTMLAttributes } from 'react';

import { Flex, Typography } from 'antd';
import cn from 'classnames';

import type { OfferRead } from 'entities/Brand';

import styles from './OfferCardForCatalog.module.scss';

interface IOfferCardForCatalogProps extends HTMLAttributes<HTMLDivElement> {
	offer: OfferRead;
}

export const OfferCardForCatalog: FC<IOfferCardForCatalogProps> = ({ className, offer, ...props }) => {
	return (
		<Flex vertical {...props} className={cn(className, styles.offerCard)}>
			<img className={styles.offerCard__image} src={offer.image} alt={offer.name} />
			<Typography.Text className={styles.offerCard__text} ellipsis={true}>
				{offer.name}
			</Typography.Text>
		</Flex>
	);
};
