import { FC, useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Link, type LinkProps } from 'react-router-dom';

import { Flex, Typography } from 'antd';
import cn from 'classnames';

import { type BrandRead } from 'entities/Brand';
import { OfferCardForCatalog } from 'entities/Offer';
import { EMainRoutes, EYmPageScreen } from 'shared/typings';
import { checkHorizontalScrollState, sendYmEvent } from 'shared/utils';

import { BrandHeader } from '../BrandHeader/BrandHeader';

import styles from './BrandCard.module.scss';

interface IBrandCardProps extends Partial<LinkProps> {
	brand: BrandRead;
}

export const BrandCard: FC<IBrandCardProps> = ({ className, brand, ...props }) => {
	const { t } = useTranslation();
	const ref = useRef<HTMLDivElement | null>(null);
	const [canScrollLeft, setCanScrollLeft] = useState<boolean>(false);
	const [canScrollRight, setCanScrollRight] = useState<boolean>(false);

	const onScroll = () => {
		checkHorizontalScrollState(ref, setCanScrollLeft, setCanScrollRight);
	};

	useEffect(() => {
		checkHorizontalScrollState(ref, setCanScrollLeft, setCanScrollRight);
	}, []);

	return (
		<Link
			{...props}
			className={cn(className, styles.brandCard)}
			to={`/${EMainRoutes.BRAND}/${brand.uuid}`}
			onClick={() => sendYmEvent('click_to_brand', { page_screen: EYmPageScreen.CATALOG_SCREEN })}>
			<BrandHeader brand={brand} isShortView />
			<Flex gap={12} className={styles.brandCard__info}>
				<Typography.Text className={styles.brandCard__average} type="secondary">
					{t('Ставка')}
				</Typography.Text>
				<Typography.Text strong>
					{Object.values(brand.grouped_rates)
						.filter((rate) => !!rate)
						.map((rate) => `${t('до')} ${rate}`)
						.join(', ')}
				</Typography.Text>
			</Flex>
			<div
				className={cn(
					styles.brandCard__wrap,
					canScrollLeft && styles.brandCard__wrap_leftOverflow,
					canScrollRight && styles.brandCard__wrap_rightOverflow,
				)}>
				<Flex gap={8} className={styles.brandCard__footer} ref={ref} onScroll={onScroll}>
					{brand.offers?.map((offer) => <OfferCardForCatalog key={offer.uuid} offer={offer} />)}
				</Flex>
			</div>
		</Link>
	);
};
