import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Flex } from 'antd';

import { BrandCard, useBrandsListQuery } from 'entities/Brand';
import { BrandsFilters, EFilters, getUrlParamsForApi, useFilters } from 'features/Filters';
import { Pagination } from 'features/Pagination';
import { NoResults, OverlayLoader } from 'shared/ui';

interface IBrandListProps extends HTMLAttributes<HTMLDivElement> {}

export const BrandList: FC<IBrandListProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const [searchParams] = useSearchParams();

	const { data, isFetching, isLoading } = useBrandsListQuery(getUrlParamsForApi(searchParams));

	const { getFiltersCount } = useFilters();
	const hasFilters = getFiltersCount([EFilters.SEARCH, EFilters.CATEGORY]) > 0;

	return (
		<Flex {...props} vertical gap={8}>
			{isFetching && <OverlayLoader />}
			<BrandsFilters />
			{!isLoading && !data?.count && (
				<NoResults
					text={t('Ничего не найдено')}
					subtext={hasFilters ? t('Нет результатов для этого поискового запроса') : t('К сожалению, пока тут ничего')}
				/>
			)}
			<Flex vertical gap={8}>
				{data?.results.map((brand) => <BrandCard brand={brand} key={brand.uuid} />)}
			</Flex>
			<Pagination count={data?.count} />
		</Flex>
	);
};
