import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Input, Select } from 'antd';

import { EFilters, OPTIONS_MAX_HEIGHT_NOTIFICATIONS, useFilters } from 'features/Filters';
import { useMetaRetrieveQuery } from 'shared/api';
import { InputClearIcon } from 'shared/ui';

interface IBrandsFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const BrandsFilters: FC<IBrandsFiltersProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { getFilterValue, onFilterChange, getALLFilterValues } = useFilters(true);
	const { data: metaData, isFetching: isMetaFetching } = useMetaRetrieveQuery();
	const [search, setSearch] = useState(getFilterValue(EFilters.SEARCH) || '');

	return (
		<Flex {...props} vertical gap={8}>
			<Input.Search
				placeholder={t('Поиск')}
				onSearch={(value) => onFilterChange(EFilters.SEARCH, value)}
				onChange={(e) => setSearch(e.target.value)}
				value={search.trimStart()}
				allowClear={{ clearIcon: <InputClearIcon /> }}
				size="large"
			/>

			<Select
				value={getALLFilterValues(EFilters.CATEGORY)}
				options={metaData?.offerCategoriesOptions || []}
				onChange={(value) => onFilterChange(EFilters.CATEGORY, value)}
				size="large"
				listHeight={OPTIONS_MAX_HEIGHT_NOTIFICATIONS}
				allowClear={{ clearIcon: <InputClearIcon /> }}
				placeholder={t('Категория бренда')}
				loading={isMetaFetching}
				mode="multiple"
			/>
		</Flex>
	);
};
